-- ───────────────── 20261202090000_video_social.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- EduFeed social: likes (♥), comments with verified TH EDU replies, share counter.
--
--   videos.likes_count / comments_count / shares_count   denormalised counters, kept exact by triggers
--   video_likes      one per (video, signed-in account) or (video, guest device)
--   video_comments   parents / guests ask, teachers & admins answer (1 level of replies) and moderate (hide)
--   video_shares     share log (a repeat share by the same person within 10 minutes is not counted again)
--
-- Identity: parents and staff are Supabase Auth users → user_id = auth.users.id (staff have no public.users
-- row). Guests are identified by a random device id stored in the app (device_id, a UUID).
-- Names and roles are decided HERE, never taken from the client for signed-in users: a parent appears as
-- "Mẹ Minh Anh" (relationship + child's given name, no surname, no phone); staff as their display name with
-- the role TEACHER / ADMIN (the app shows the "Giáo viên TH EDU" / "Quản trị viên" badge from the role).
-- Guests choose a display name, but names that impersonate the centre are refused.
--
-- Anti-spam (guests and parents): 1–500 characters, no links, max 5 comments / 10 minutes and 30 / day per
-- person or device, no identical repeat within 10 minutes, and a ceiling of 300 guest comments / hour in total.
--
-- Access: comments are publicly readable when visible (RLS: is_hidden = false on a published video; staff
-- also see hidden ones). Every write goes through the functions below (they enforce the rules above);
-- likes / shares tables are not readable by clients (they hold device ids).
-- ═══════════════════════════════════════════════════════════════════════════

alter table public.videos
  add column if not exists likes_count    int not null default 0 check (likes_count >= 0),
  add column if not exists comments_count int not null default 0 check (comments_count >= 0),
  add column if not exists shares_count   int not null default 0 check (shares_count >= 0);

create table if not exists public.video_likes (
  id          uuid primary key default gen_random_uuid(),
  video_id    uuid not null references public.videos (id) on delete cascade,
  user_id     uuid references auth.users (id) on delete cascade,
  device_id   text check (device_id is null or device_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'),
  created_at  timestamptz not null default now(),
  check (user_id is not null or device_id is not null),
  unique (video_id, user_id),
  unique (video_id, device_id)
);

create table if not exists public.video_comments (
  id                 uuid primary key default gen_random_uuid(),
  video_id           uuid not null references public.videos (id) on delete cascade,
  user_id            uuid references auth.users (id) on delete set null,
  device_id          text check (device_id is null or device_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'),
  author_name        text not null check (char_length(btrim(author_name)) between 2 and 60),
  author_role        text not null check (author_role in ('PARENT', 'TEACHER', 'ADMIN', 'GUEST')),
  content            text not null check (char_length(btrim(content)) between 1 and 500),
  parent_comment_id  uuid references public.video_comments (id) on delete cascade,
  is_hidden          boolean not null default false,
  hidden_by          uuid references auth.users (id) on delete set null,
  hidden_at          timestamptz,
  created_at         timestamptz not null default now()
);
create index if not exists video_comments_video_idx on public.video_comments (video_id, created_at desc);
create index if not exists video_comments_parent_idx on public.video_comments (parent_comment_id) where parent_comment_id is not null;
create index if not exists video_comments_user_idx on public.video_comments (user_id, created_at desc) where user_id is not null;
create index if not exists video_comments_device_idx on public.video_comments (device_id, created_at desc) where device_id is not null;

create table if not exists public.video_shares (
  id          uuid primary key default gen_random_uuid(),
  video_id    uuid not null references public.videos (id) on delete cascade,
  actor_key   text not null,
  channel     text not null default 'NATIVE' check (channel in ('NATIVE', 'ZALO', 'COPY')),
  created_at  timestamptz not null default now()
);
create index if not exists video_shares_actor_idx on public.video_shares (video_id, actor_key, created_at desc);

-- ─── Counters (exact, atomic) ───────────────────────────────────────────────

create or replace function public.video_likes_count_trg()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'INSERT' then
    update public.videos set likes_count = likes_count + 1 where id = new.video_id;
  elsif tg_op = 'DELETE' then
    update public.videos set likes_count = greatest(likes_count - 1, 0) where id = old.video_id;
  end if;
  return null;
end $$;

drop trigger if exists video_likes_count on public.video_likes;
create trigger video_likes_count after insert or delete on public.video_likes
  for each row execute function public.video_likes_count_trg();

-- comments_count = visible comments (replies included).
create or replace function public.video_comments_count_trg()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'INSERT' and not new.is_hidden then
    update public.videos set comments_count = comments_count + 1 where id = new.video_id;
  elsif tg_op = 'DELETE' and not old.is_hidden then
    update public.videos set comments_count = greatest(comments_count - 1, 0) where id = old.video_id;
  elsif tg_op = 'UPDATE' and new.is_hidden is distinct from old.is_hidden then
    update public.videos set comments_count = greatest(comments_count + case when new.is_hidden then -1 else 1 end, 0) where id = new.video_id;
  end if;
  return null;
end $$;

drop trigger if exists video_comments_count on public.video_comments;
create trigger video_comments_count after insert or update of is_hidden or delete on public.video_comments
  for each row execute function public.video_comments_count_trg();

-- Published (and visible now) — used by the read policy and every write function.
create or replace function public.social_video_published(p_video_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$ select exists (select 1 from public.videos where id = p_video_id and is_published and published_at <= now()) $$;

-- ─── Row level security ─────────────────────────────────────────────────────

alter table public.video_likes enable row level security;
alter table public.video_comments enable row level security;
alter table public.video_shares enable row level security;

drop policy if exists "public reads visible comments, staff read all" on public.video_comments;
create policy "public reads visible comments, staff read all" on public.video_comments for select to anon, authenticated
  using (
    (not is_hidden and public.social_video_published(video_id))
    or public.is_staff()
  );

revoke all on public.video_likes, public.video_shares, public.video_comments from anon, authenticated;
-- Public columns only: who wrote it is shown by name / role; account and device ids stay private.
grant select (id, video_id, author_name, author_role, content, parent_comment_id, is_hidden, created_at)
  on public.video_comments to anon, authenticated;

-- ─── Helpers ────────────────────────────────────────────────────────────────

create or replace function public.social_valid_device(p_device_id text)
returns boolean
language sql
immutable
as $$ select coalesce(p_device_id, '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' $$;

-- "Nguyễn Minh Anh" → "Minh Anh"; "Minh Khôi" → "Minh Khôi" (no surname on a public page).
create or replace function public.social_given_name(p_full text)
returns text
language sql
immutable
as $$
  select case when array_length(w, 1) >= 3 then array_to_string(w[array_length(w, 1) - 1:], ' ') else array_to_string(w, ' ') end
  from (select regexp_split_to_array(btrim(regexp_replace(coalesce(p_full, ''), '\s*\(.*?\)\s*', ' ', 'g')), '\s+') w) t;
$$;

-- Who is commenting: role + public display name (null role = not signed in).
create or replace function public.social_actor()
returns table (actor_role text, actor_name text)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_parent uuid := public.current_parent_id();
  v_kind   text;
begin
  if auth.uid() is null then
    return query select null::text, null::text;
    return;
  end if;
  if v_parent is not null then
    return query
      select 'PARENT'::text,
             coalesce((
               select (case l.relationship when 'MOM' then 'Mẹ ' when 'DAD' then 'Bố ' else 'Phụ huynh bé ' end) || public.social_given_name(s.full_name)
               from public.parent_student_links l join public.students s on s.id = l.student_id
               where l.parent_id = v_parent order by l.is_primary desc, l.created_at limit 1),
               'Phụ huynh ' || public.social_given_name((select full_name from public.users where id = v_parent)));
    return;
  end if;
  if public.is_staff() then
    v_kind := public.staff_kind();
    return query
      select case when v_kind in ('ADMIN', 'MANAGER') then 'ADMIN' else 'TEACHER' end,
             left(coalesce(
               (select nullif(btrim(display_name), '') from public.staff_profiles where user_id = auth.uid()),
               (select nullif(btrim(raw_user_meta_data ->> 'full_name'), '') from auth.users where id = auth.uid()),
               'TH EDU'), 60);
    return;
  end if;
  return query select null::text, null::text;
end $$;


-- ─── Likes ──────────────────────────────────────────────────────────────────
-- p_liked: null = toggle, true = like (double-tap: never un-likes), false = unlike.
-- A signed-in user who liked as a guest on this phone keeps that like (no double count).
create or replace function public.toggle_video_like(p_video_id uuid, p_device_id text default null, p_liked boolean default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_uid    uuid := auth.uid();
  v_dev    text := case when public.social_valid_device(p_device_id) then p_device_id end;
  v_has    boolean;
  v_want   boolean;
  v_count  int;
begin
  if not public.social_video_published(p_video_id) then
    raise exception 'Không tìm thấy video' using hint = 'NOT_FOUND';
  end if;
  if v_uid is null and v_dev is null then
    raise exception 'Thiếu mã thiết bị' using hint = 'VALIDATION:device';
  end if;
  v_has := exists (select 1 from public.video_likes where video_id = p_video_id
                    and ((v_uid is not null and user_id = v_uid) or (v_dev is not null and device_id = v_dev and (user_id is null or user_id = v_uid))));
  v_want := coalesce(p_liked, not v_has);
  if v_want and not v_has then
    insert into public.video_likes (video_id, user_id, device_id)
    values (p_video_id, v_uid, case when v_uid is null then v_dev end)
    on conflict do nothing;
  elsif not v_want and v_has then
    delete from public.video_likes where video_id = p_video_id
      and ((v_uid is not null and user_id = v_uid) or (v_dev is not null and device_id = v_dev and (user_id is null or user_id = v_uid)));
  end if;
  select likes_count into v_count from public.videos where id = p_video_id;
  return jsonb_build_object('liked', v_want, 'likes_count', v_count);
end $$;

-- ─── Comments ───────────────────────────────────────────────────────────────

create or replace function public.add_video_comment(
  p_video_id uuid, p_content text, p_parent_comment_id uuid default null, p_guest_name text default null, p_device_id text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_uid      uuid := auth.uid();
  v_dev      text := case when public.social_valid_device(p_device_id) then p_device_id end;
  v_role     text;
  v_name     text;
  v_content  text := btrim(regexp_replace(coalesce(p_content, ''), '\n{3,}', E'\n\n', 'g'));
  v_parent   public.video_comments;
  v_row      public.video_comments;
  v_staff    boolean;
begin
  if not public.social_video_published(p_video_id) then
    raise exception 'Không tìm thấy video' using hint = 'NOT_FOUND';
  end if;
  select a.actor_role, a.actor_name into v_role, v_name from public.social_actor() a;
  v_staff := coalesce(v_role in ('TEACHER', 'ADMIN'), false);

  if char_length(v_content) < 1 then
    raise exception 'Ba mẹ nhập nội dung bình luận nhé' using hint = 'VALIDATION:content';
  end if;
  if char_length(v_content) > 500 then
    raise exception 'Bình luận tối đa 500 ký tự' using hint = 'VALIDATION:content';
  end if;

  if v_role is null then
    -- Guest
    if v_dev is null then
      raise exception 'Thiếu mã thiết bị' using hint = 'VALIDATION:device';
    end if;
    v_name := btrim(regexp_replace(coalesce(p_guest_name, ''), '\s+', ' ', 'g'));
    if char_length(v_name) not between 2 and 40 then
      raise exception 'Tên hiển thị 2–40 ký tự' using hint = 'VALIDATION:name';
    end if;
    if lower(v_name) ~ '(th\s*edu|giáo\s*viên|giao\s*vien|quản\s*trị|quan\s*tri|admin|trung\s*tâm|trung\s*tam|ban\s*giám|ban\s*giam)' then
      raise exception 'Tên này dành cho trung tâm, ba mẹ chọn tên khác nhé' using hint = 'VALIDATION:name';
    end if;
    v_role := 'GUEST';
    if (select count(*) from public.video_comments where user_id is null and device_id is not null and created_at > now() - interval '1 hour') >= 300 then
      raise exception 'Hệ thống đang bận, ba mẹ thử lại sau ít phút' using hint = 'RATE_LIMIT';
    end if;
  end if;

  if not v_staff then
    if v_content ~* '(https?://|www\.|(^|[^a-z0-9])[a-z0-9-]{2,}\.(com|vn|net|org|info|xyz|io|me|ly|link)([^a-z0-9]|$))' then
      raise exception 'Bình luận không được chứa đường link' using hint = 'VALIDATION:content';
    end if;
    if (select count(*) from public.video_comments
         where (case when v_uid is not null then user_id = v_uid else device_id = v_dev and user_id is null end)
           and created_at > now() - interval '10 minutes') >= 5
       or (select count(*) from public.video_comments
         where (case when v_uid is not null then user_id = v_uid else device_id = v_dev and user_id is null end)
           and created_at > now() - interval '1 day') >= 30 then
      raise exception 'Ba mẹ bình luận hơi nhanh, thử lại sau ít phút nhé' using hint = 'RATE_LIMIT';
    end if;
    if exists (select 1 from public.video_comments
                where (case when v_uid is not null then user_id = v_uid else device_id = v_dev and user_id is null end)
                  and video_id = p_video_id and lower(content) = lower(v_content) and created_at > now() - interval '10 minutes') then
      raise exception 'Bình luận này vừa được gửi rồi' using hint = 'CONFLICT';
    end if;
  end if;

  if p_parent_comment_id is not null then
    if not v_staff then
      raise exception 'Chỉ giáo viên / quản trị viên TH EDU được trả lời bình luận' using hint = 'FORBIDDEN';
    end if;
    select * into v_parent from public.video_comments where id = p_parent_comment_id;
    if not found or v_parent.video_id <> p_video_id then
      raise exception 'Không tìm thấy bình luận cần trả lời' using hint = 'NOT_FOUND';
    end if;
    if v_parent.parent_comment_id is not null then
      p_parent_comment_id := v_parent.parent_comment_id; -- keep one level: reply in the same thread
    end if;
  end if;

  insert into public.video_comments (video_id, user_id, device_id, author_name, author_role, content, parent_comment_id)
  values (p_video_id, v_uid, case when v_uid is null then v_dev end, v_name, v_role, v_content, p_parent_comment_id)
  returning * into v_row;

  return jsonb_build_object(
    'id', v_row.id, 'video_id', v_row.video_id, 'author_name', v_row.author_name, 'author_role', v_row.author_role,
    'content', v_row.content, 'parent_comment_id', v_row.parent_comment_id, 'is_hidden', v_row.is_hidden,
    'created_at', v_row.created_at, 'mine', true,
    'comments_count', (select comments_count from public.videos where id = p_video_id));
end $$;

-- Threads, newest first; replies oldest first under their comment. Staff also get hidden comments (flagged).
create or replace function public.get_video_comments(p_video_id uuid, p_device_id text default null, p_limit int default 30, p_before timestamptz default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_staff boolean := public.is_staff();
  v_uid   uuid := auth.uid();
  v_dev   text := case when public.social_valid_device(p_device_id) then p_device_id end;
begin
  if not public.social_video_published(p_video_id) and not v_staff then
    raise exception 'Không tìm thấy video' using hint = 'NOT_FOUND';
  end if;
  return jsonb_build_object(
    'comments_count', (select comments_count from public.videos where id = p_video_id),
    'can_moderate', v_staff,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', c.id, 'author_name', c.author_name, 'author_role', c.author_role, 'content', c.content,
        'is_hidden', c.is_hidden, 'created_at', c.created_at,
        'mine', coalesce((v_uid is not null and c.user_id = v_uid) or (v_uid is null and v_dev is not null and c.device_id = v_dev), false),
        'replies', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', r.id, 'author_name', r.author_name, 'author_role', r.author_role, 'content', r.content,
            'is_hidden', r.is_hidden, 'created_at', r.created_at, 'parent_comment_id', r.parent_comment_id,
            'mine', coalesce(v_uid is not null and r.user_id = v_uid, false)) order by r.created_at)
          from public.video_comments r
          where r.parent_comment_id = c.id and (v_staff or not r.is_hidden)), '[]'::jsonb))
        order by c.created_at desc)
      from (select * from public.video_comments x
             where x.video_id = p_video_id and x.parent_comment_id is null and (v_staff or not x.is_hidden)
               and (p_before is null or x.created_at < p_before)
             order by x.created_at desc
             limit least(greatest(coalesce(p_limit, 30), 1), 100)) c), '[]'::jsonb));
end $$;

-- Teachers / admins: hide (or show again) a comment. Hiding a comment hides its thread from the public.
create or replace function public.hide_video_comment(p_comment_id uuid, p_hidden boolean default true)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_row public.video_comments;
begin
  if not public.is_staff() then
    raise exception 'Chỉ giáo viên / quản trị viên được ẩn bình luận' using hint = 'FORBIDDEN';
  end if;
  update public.video_comments
     set is_hidden = coalesce(p_hidden, true),
         hidden_by = case when coalesce(p_hidden, true) then auth.uid() end,
         hidden_at = case when coalesce(p_hidden, true) then now() end
   where id = p_comment_id
  returning * into v_row;
  if not found then
    raise exception 'Không tìm thấy bình luận' using hint = 'NOT_FOUND';
  end if;
  -- A hidden question takes its answers with it (keeps comments_count = what the public sees).
  if v_row.parent_comment_id is null then
    update public.video_comments
       set is_hidden = v_row.is_hidden, hidden_by = v_row.hidden_by, hidden_at = v_row.hidden_at
     where parent_comment_id = v_row.id and is_hidden is distinct from v_row.is_hidden;
  end if;
  return jsonb_build_object('id', v_row.id, 'is_hidden', v_row.is_hidden,
                            'comments_count', (select comments_count from public.videos where id = v_row.video_id));
end $$;

-- ─── Shares ─────────────────────────────────────────────────────────────────

create or replace function public.increment_video_share(p_video_id uuid, p_device_id text default null, p_channel text default 'NATIVE')
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_key   text := coalesce(auth.uid()::text, case when public.social_valid_device(p_device_id) then 'd:' || p_device_id end);
  v_count int;
  v_new   boolean := false;
begin
  if not public.social_video_published(p_video_id) then
    raise exception 'Không tìm thấy video' using hint = 'NOT_FOUND';
  end if;
  if v_key is null then
    raise exception 'Thiếu mã thiết bị' using hint = 'VALIDATION:device';
  end if;
  if not exists (select 1 from public.video_shares where video_id = p_video_id and actor_key = v_key and created_at > now() - interval '10 minutes') then
    insert into public.video_shares (video_id, actor_key, channel)
    values (p_video_id, v_key, case when p_channel in ('NATIVE', 'ZALO', 'COPY') then p_channel else 'NATIVE' end);
    update public.videos set shares_count = shares_count + 1 where id = p_video_id returning shares_count into v_count;
    v_new := true;
  else
    select shares_count into v_count from public.videos where id = p_video_id;
  end if;
  return jsonb_build_object('shares_count', v_count, 'counted', v_new);
end $$;

-- ─── Feed: counters + "did I like it" for a page of videos ─────────────────

create or replace function public.video_social_state(p_video_ids uuid[], p_device_id text default null)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', v.id, 'likes_count', v.likes_count, 'comments_count', v.comments_count, 'shares_count', v.shares_count,
    'liked', exists (select 1 from public.video_likes l where l.video_id = v.id
                      and ((auth.uid() is not null and l.user_id = auth.uid())
                           or (public.social_valid_device(p_device_id) and l.device_id = p_device_id and (l.user_id is null or l.user_id = auth.uid())))))), '[]'::jsonb)
  from public.videos v
  where v.id = any ((p_video_ids)[1:60]) and v.is_published;
$$;

