revoke all on function public.video_likes_count_trg() from public;
revoke all on function public.video_comments_count_trg() from public;
revoke all on function public.social_actor() from public;
revoke all on function public.toggle_video_like(uuid, text, boolean) from public;
revoke all on function public.add_video_comment(uuid, text, uuid, text, text) from public;
revoke all on function public.get_video_comments(uuid, text, int, timestamptz) from public;
revoke all on function public.hide_video_comment(uuid, boolean) from public;
revoke all on function public.increment_video_share(uuid, text, text) from public;
revoke all on function public.video_social_state(uuid[], text) from public;

grant execute on function public.social_valid_device(text) to anon, authenticated;
grant execute on function public.social_given_name(text) to anon, authenticated;
grant execute on function public.social_video_published(uuid) to anon, authenticated;
grant execute on function public.toggle_video_like(uuid, text, boolean) to anon, authenticated;
grant execute on function public.add_video_comment(uuid, text, uuid, text, text) to anon, authenticated;
grant execute on function public.get_video_comments(uuid, text, int, timestamptz) to anon, authenticated;
grant execute on function public.hide_video_comment(uuid, boolean) to authenticated;
grant execute on function public.increment_video_share(uuid, text, text) to anon, authenticated;
grant execute on function public.video_social_state(uuid[], text) to anon, authenticated;

-- ───────────────── 20261203090000_account_center.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Account center ("Cài đặt & Tài khoản"): one profile API for every signed-in role,
-- self-service name / avatar, in-app account deletion requests (App Store / Google Play),
-- and an admin editor for the store version gate (app_release_config).
--
--   my_account()                       → who am I (role, name, phone, email, avatar, campus, Zalo, deletion)
--   update_my_profile(name, avatar)    → parent: users · staff: staff_profiles
--   request_account_deletion(reason)   → one pending request per account
--   cancel_account_deletion()
--   admin_deletion_requests(status)    → admin list
--   admin_resolve_deletion(id, status) → DONE deactivates a parent account / CANCELLED
--   admin_release_config_save(...)     → upsert one platform row
--
-- Avatars: public bucket "avatars", each account writes only inside its own <auth uid>/ folder.
-- ═══════════════════════════════════════════════════════════════════════════

alter table public.staff_profiles add column if not exists avatar_url text;

alter table public.users drop constraint if exists users_avatar_url_check;
-- NOT VALID: rows written before this migration are left alone; every new write is checked.
alter table public.users add constraint users_avatar_url_check check (avatar_url is null or (avatar_url ~* '^https://' and char_length(avatar_url) <= 500)) not valid;
alter table public.staff_profiles drop constraint if exists staff_profiles_avatar_url_check;
alter table public.staff_profiles add constraint staff_profiles_avatar_url_check check (avatar_url is null or (avatar_url ~* '^https://' and char_length(avatar_url) <= 500));

-- ─── Deletion requests ──────────────────────────────────────────────────────

create table if not exists public.account_deletion_requests (
  id            uuid primary key default gen_random_uuid(),
  auth_user_id  uuid not null references auth.users (id) on delete cascade,
  role          text not null check (role in ('PARENT', 'TEACHER', 'ADVISOR', 'MANAGER', 'ADMIN')),
  display_name  text not null,
  contact       text not null,
  reason        text check (reason is null or char_length(reason) <= 500),
  status        text not null default 'PENDING' check (status in ('PENDING', 'DONE', 'CANCELLED')),
  handled_by    uuid references auth.users (id) on delete set null,
  handled_at    timestamptz,
  created_at    timestamptz not null default now()
);
create unique index if not exists account_deletion_one_pending on public.account_deletion_requests (auth_user_id) where status = 'PENDING';

alter table public.account_deletion_requests enable row level security;
revoke all on public.account_deletion_requests from anon, authenticated;

-- ─── Helpers ────────────────────────────────────────────────────────────────

create or replace function public.account_role()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select case
    when public.is_staff() then public.staff_kind()
    when public.current_parent_id() is not null then 'PARENT'
  end;
$$;
grant execute on function public.account_role() to authenticated;

-- ─── my_account ─────────────────────────────────────────────────────────────

create or replace function public.my_account()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_role text := public.account_role();
  v_uid uuid := auth.uid();
  v_email text;
  v_out jsonb;
begin
  if v_uid is null or v_role is null then
    raise exception 'Cần đăng nhập' using hint = 'UNAUTHORIZED';
  end if;
  select email into v_email from auth.users where id = v_uid;

  if v_role = 'PARENT' then
    select jsonb_build_object(
      'role', 'PARENT', 'fullName', u.full_name, 'phone', u.phone, 'email', null, 'avatarUrl', u.avatar_url,
      'campus', (select s.campus_location from public.parent_student_links l join public.students s on s.id = l.student_id
                 where l.parent_id = u.id order by l.is_primary desc, l.created_at limit 1),
      'zaloLinked', u.zalo_id is not null)
      into v_out
      from public.users u where u.id = public.current_parent_id();
  else
    select jsonb_build_object(
      'role', v_role,
      'fullName', coalesce(p.display_name, split_part(coalesce(v_email, ''), '@', 1)),
      'phone', p.phone, 'email', v_email, 'avatarUrl', p.avatar_url, 'campus', p.campus_location, 'zaloLinked', false)
      into v_out
      from (select 1) x left join public.staff_profiles p on p.user_id = v_uid;
  end if;

  return v_out || jsonb_build_object('deletionPending',
    exists (select 1 from public.account_deletion_requests d where d.auth_user_id = v_uid and d.status = 'PENDING'));
end $$;
grant execute on function public.my_account() to authenticated;

-- ─── update_my_profile ──────────────────────────────────────────────────────

create or replace function public.update_my_profile(p_full_name text, p_avatar_url text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role text := public.account_role();
  v_name text := btrim(coalesce(p_full_name, ''));
  v_avatar text := nullif(btrim(coalesce(p_avatar_url, '')), '');
begin
  if auth.uid() is null or v_role is null then
    raise exception 'Cần đăng nhập' using hint = 'UNAUTHORIZED';
  end if;
  if char_length(v_name) < 2 or char_length(v_name) > 60 then
    raise exception 'Tên cần từ 2 đến 60 ký tự' using hint = 'VALIDATION:fullName';
  end if;
  if v_name ~ '[<>{}]|https?://' then
    raise exception 'Tên không được chứa đường link hay ký tự đặc biệt' using hint = 'VALIDATION:fullName';
  end if;
  if v_avatar is not null and (v_avatar !~* '^https://' or char_length(v_avatar) > 500) then
    raise exception 'Ảnh đại diện không hợp lệ' using hint = 'VALIDATION:avatar';
  end if;

  if v_role = 'PARENT' then
    update public.users set full_name = v_name, avatar_url = v_avatar where id = public.current_parent_id();
  else
    insert into public.staff_profiles (user_id, kind, display_name, avatar_url, updated_by)
    values (auth.uid(), case when v_role in ('TEACHER', 'ADVISOR') then v_role else 'MANAGER' end, v_name, v_avatar, auth.uid())
    on conflict (user_id) do update set display_name = excluded.display_name, avatar_url = excluded.avatar_url,
                                       updated_by = auth.uid(), updated_at = now();
  end if;
  return public.my_account();
end $$;
grant execute on function public.update_my_profile(text, text) to authenticated;

-- ─── Deletion: self-service ─────────────────────────────────────────────────

create or replace function public.request_account_deletion(p_reason text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_me jsonb := public.my_account();
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if v_reason is not null and char_length(v_reason) > 500 then
    raise exception 'Lý do tối đa 500 ký tự' using hint = 'VALIDATION:reason';
  end if;
  if (v_me ->> 'deletionPending')::boolean then
    raise exception 'Yêu cầu xoá tài khoản đã được gửi, trung tâm đang xử lý' using hint = 'CONFLICT';
  end if;
  insert into public.account_deletion_requests (auth_user_id, role, display_name, contact, reason)
  values (auth.uid(), v_me ->> 'role', v_me ->> 'fullName', coalesce(v_me ->> 'phone', v_me ->> 'email', ''), v_reason);
  return public.my_account();
end $$;
grant execute on function public.request_account_deletion(text) to authenticated;

create or replace function public.cancel_account_deletion()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or public.account_role() is null then
    raise exception 'Cần đăng nhập' using hint = 'UNAUTHORIZED';
  end if;
  update public.account_deletion_requests set status = 'CANCELLED', handled_by = auth.uid(), handled_at = now()
   where auth_user_id = auth.uid() and status = 'PENDING';
  return public.my_account();
end $$;
grant execute on function public.cancel_account_deletion() to authenticated;

-- ─── Deletion: admin ────────────────────────────────────────────────────────

create or replace function public.admin_deletion_requests(p_status text default 'PENDING')
returns table (id uuid, role text, display_name text, contact text, reason text, status text, created_at timestamptz, handled_at timestamptz)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'Chỉ quản trị viên' using hint = 'FORBIDDEN';
  end if;
  return query
    select d.id, d.role, d.display_name, d.contact, d.reason, d.status, d.created_at, d.handled_at
      from public.account_deletion_requests d
     where p_status is null or d.status = p_status
     order by d.created_at desc
     limit 200;
end $$;
grant execute on function public.admin_deletion_requests(text) to authenticated;

create or replace function public.admin_resolve_deletion(p_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_req public.account_deletion_requests;
begin
  if not public.is_admin() then
    raise exception 'Chỉ quản trị viên' using hint = 'FORBIDDEN';
  end if;
  if p_status not in ('DONE', 'CANCELLED') then
    raise exception 'Trạng thái không hợp lệ' using hint = 'VALIDATION:status';
  end if;
  select * into v_req from public.account_deletion_requests where id = p_id for update;
  if not found then
    raise exception 'Không tìm thấy yêu cầu' using hint = 'NOT_FOUND';
  end if;
  if v_req.status <> 'PENDING' then
    raise exception 'Yêu cầu đã được xử lý' using hint = 'CONFLICT';
  end if;
  update public.account_deletion_requests set status = p_status, handled_by = auth.uid(), handled_at = now() where id = p_id;
  -- DONE on a parent: the account stops signing in and its personal details are cleared.
  -- (The child's learning history stays with the centre; staff accounts are disabled in Tài khoản nhân viên.)
  if p_status = 'DONE' and v_req.role = 'PARENT' then
    update public.users set is_active = false, avatar_url = null, zalo_id = null where auth_user_id = v_req.auth_user_id;
  end if;
end $$;
grant execute on function public.admin_resolve_deletion(uuid, text) to authenticated;

-- ─── Release config: admin editor ───────────────────────────────────────────

create or replace function public.admin_release_config_save(
  p_platform text, p_min_supported_version text, p_latest_version text,
  p_store_url text, p_release_notes_vi text, p_is_force_update boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'Chỉ quản trị viên' using hint = 'FORBIDDEN';
  end if;
  if p_platform not in ('android', 'ios') then
    raise exception 'Nền tảng không hợp lệ' using hint = 'VALIDATION:platform';
  end if;
  if coalesce(p_min_supported_version, '') !~ '^\d{1,6}(\.\d{1,6}){0,2}$' then
    raise exception 'Phiên bản tối thiểu dạng 1.2.3' using hint = 'VALIDATION:minSupportedVersion';
  end if;
  if coalesce(p_latest_version, '') !~ '^\d{1,6}(\.\d{1,6}){0,2}$' then
    raise exception 'Phiên bản mới nhất dạng 1.2.3' using hint = 'VALIDATION:latestVersion';
  end if;
  if coalesce(p_store_url, '') <> '' and p_store_url !~* '^https://' then
    raise exception 'Link cửa hàng phải bắt đầu bằng https://' using hint = 'VALIDATION:storeUrl';
  end if;
  if char_length(coalesce(p_release_notes_vi, '')) > 600 then
    raise exception 'Ghi chú tối đa 600 ký tự' using hint = 'VALIDATION:releaseNotesVi';
  end if;
  insert into public.app_release_config (platform, min_supported_version, latest_version, store_url, release_notes_vi, is_force_update)
  values (p_platform, p_min_supported_version, p_latest_version, coalesce(p_store_url, ''), coalesce(p_release_notes_vi, ''), coalesce(p_is_force_update, false))
  on conflict (platform) do update set
    min_supported_version = excluded.min_supported_version, latest_version = excluded.latest_version,
    store_url = excluded.store_url, release_notes_vi = excluded.release_notes_vi, is_force_update = excluded.is_force_update;
end $$;
grant execute on function public.admin_release_config_save(text, text, text, text, text, boolean) to authenticated;

-- ─── Avatars bucket ─────────────────────────────────────────────────────────

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('avatars', 'avatars', true, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "own avatar upload" on storage.objects;
create policy "own avatar upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'avatars' and split_part(name, '/', 1) = auth.uid()::text);
drop policy if exists "own avatar update" on storage.objects;
create policy "own avatar update" on storage.objects for update to authenticated
  using (bucket_id = 'avatars' and split_part(name, '/', 1) = auth.uid()::text);
drop policy if exists "own avatar delete" on storage.objects;
create policy "own avatar delete" on storage.objects for delete to authenticated
  using (bucket_id = 'avatars' and split_part(name, '/', 1) = auth.uid()::text);

-- ───────────────── 20261204090000_admin_command_center.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Admin Command Center: the numbers and queues the owner needs on one screen.
--
--   ad_spend                         monthly ad spend per channel (+ branch) → CPA
--   admin_ad_spend_save(...)         upsert one month / channel / branch
--   admin_command_overview(b, days)  tuition collected vs unpaid, trial attendance, revenue per course,
--                                    spend + CPA per channel, recent invoices, ops queues
--   admin_class_report_status(b, d)  classes meeting on a day vs sổ liên lạc / điểm danh already sent
--   admin_recent_comments(...)       EduFeed comments across all videos (moderation)
--   admin_system_health()            push outbox, device tokens, weekly digest, Zalo OA token
--
-- Everything is read-only except ad_spend; every function is admin-only (is_admin()).
-- ═══════════════════════════════════════════════════════════════════════════

create table if not exists public.ad_spend (
  id           uuid primary key default gen_random_uuid(),
  -- '' = both campuses (unique key needs a value; exposed as null).
  branch_key   text not null default '' check (branch_key = '' or branch_key in ('XA_LA', 'NGO_THI_NHAM')),
  channel      text not null check (channel in ('FACEBOOK', 'TIKTOK', 'ZALO', 'REFERRAL', 'OTHER')),
  month_start  date not null check (extract(day from month_start) = 1),
  amount_vnd   bigint not null check (amount_vnd between 0 and 10000000000),
  note         text check (note is null or char_length(note) <= 200),
  updated_by   uuid references auth.users (id) on delete set null,
  updated_at   timestamptz not null default now(),
  unique (branch_key, channel, month_start)
);
alter table public.ad_spend enable row level security;
revoke all on public.ad_spend from anon, authenticated;

create or replace function public.admin_guard()
returns void
language plpgsql
stable
as $$
begin
  if not public.is_admin() then
    raise exception 'Chỉ quản trị viên' using hint = 'FORBIDDEN';
  end if;
end $$;

create or replace function public.admin_branch_check(p_branch text)
returns void
language plpgsql
stable
as $$
begin
  if p_branch is not null and p_branch not in ('XA_LA', 'NGO_THI_NHAM') then
    raise exception 'Cơ sở không tồn tại' using hint = 'VALIDATION:branch';
  end if;
end $$;

-- ─── Ad spend ───────────────────────────────────────────────────────────────

create or replace function public.admin_ad_spend_save(p_branch text, p_channel text, p_month date, p_amount_vnd bigint, p_note text default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.admin_guard();
  perform public.admin_branch_check(p_branch);
  if p_channel not in ('FACEBOOK', 'TIKTOK', 'ZALO', 'REFERRAL', 'OTHER') then
    raise exception 'Kênh không hợp lệ' using hint = 'VALIDATION:channel';
  end if;
  if p_month is null then
    raise exception 'Chọn tháng' using hint = 'VALIDATION:month';
  end if;
  if p_amount_vnd is null or p_amount_vnd < 0 or p_amount_vnd > 10000000000 then
    raise exception 'Số tiền không hợp lệ' using hint = 'VALIDATION:amount';
  end if;
  insert into public.ad_spend (branch_key, channel, month_start, amount_vnd, note, updated_by)
  values (coalesce(p_branch, ''), p_channel, date_trunc('month', p_month)::date, p_amount_vnd, nullif(btrim(coalesce(p_note, '')), ''), auth.uid())
  on conflict (branch_key, channel, month_start) do update
    set amount_vnd = excluded.amount_vnd, note = excluded.note, updated_by = auth.uid(), updated_at = now();
end $$;
grant execute on function public.admin_ad_spend_save(text, text, date, bigint, text) to authenticated;

-- ─── Overview ───────────────────────────────────────────────────────────────

create or replace function public.admin_command_overview(p_branch text default null, p_days int default 30, p_now timestamptz default now())
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_days  int := least(greatest(coalesce(p_days, 30), 1), 365);
  v_today date := (p_now at time zone 'Asia/Ho_Chi_Minh')::date;
  -- "Hôm nay" (1 day) = since local midnight; N days = the last N local days including today.
  v_from  timestamptz := ((v_today - (v_days - 1)) :: timestamp) at time zone 'Asia/Ho_Chi_Minh';
  v_from_d date := v_today - (v_days - 1);
  v_out   jsonb;
begin
  perform public.admin_guard();
  perform public.admin_branch_check(p_branch);

  with
  l as (select * from public.leads where (p_branch is null or branch_location = p_branch) and created_at >= v_from and created_at <= p_now),
  trials as (
    -- Trials whose appointment fell in the period (up to now): did the child come?
    select * from public.leads
     where (p_branch is null or branch_location = p_branch)
       and appointment_time >= v_from and appointment_time <= p_now
       and status <> 'CANCELLED'
  ),
  inv as (select * from public.tuition_invoices where p_branch is null or campus_location = p_branch),
  paid as (select * from inv where status = 'PAID' and paid_at >= v_from and paid_at <= p_now),
  spend as (
    select channel, sum(amount_vnd)::bigint amount
      from public.ad_spend
     where (p_branch is null or branch_key in ('', p_branch))
       and month_start >= date_trunc('month', v_from_d)::date and month_start <= v_today
     group by channel
  ),
  ch as (
    select c.channel,
           (select count(*) from l where l.channel = c.channel) leads,
           (select count(*) from l where l.channel = c.channel and l.status = 'ENROLLED') enrolled,
           coalesce((select amount from spend s where s.channel = c.channel), 0) spend
      from (values ('FACEBOOK'), ('TIKTOK'), ('ZALO'), ('REFERRAL'), ('OTHER'), ('UNTRACKED')) as c(channel)
  )
  select jsonb_build_object(
    'period', jsonb_build_object('from', v_from, 'to', p_now, 'days', v_days),
    'leads', jsonb_build_object(
      'total', (select count(*) from l),
      'enrolled', (select count(*) from l where status = 'ENROLLED'),
      'cancelled', (select count(*) from l where status = 'CANCELLED')),
    'trials', jsonb_build_object(
      'scheduled', (select count(*) from trials),
      'attended', (select count(*) from trials where trial_completed_at is not null or status in ('COMPLETED_TRIAL', 'ENROLLED'))),
    'tuition', jsonb_build_object(
      'collectedVnd', coalesce((select sum(coalesce(paid_amount_vnd, amount_vnd)) from paid), 0),
      'paidCount', (select count(*) from paid),
      'unpaidVnd', coalesce((select sum(amount_vnd) from inv where status = 'PENDING_PAYMENT'), 0),
      'unpaidCount', (select count(*) from inv where status = 'PENDING_PAYMENT')),
    'revenueByCourse', coalesce((
      select jsonb_agg(jsonb_build_object('course', course_code, 'amountVnd', amt, 'count', n) order by amt desc)
        from (select course_code, sum(coalesce(paid_amount_vnd, amount_vnd)) amt, count(*) n from paid group by course_code) x), '[]'::jsonb),
    'channels', coalesce((
      select jsonb_agg(jsonb_build_object('channel', channel, 'leads', leads, 'enrolled', enrolled, 'spendVnd', spend,
                                          'cpaVnd', case when leads > 0 and spend > 0 then round(spend::numeric / leads) end))
        from ch where leads > 0 or spend > 0), '[]'::jsonb),
    'spendVnd', coalesce((select sum(amount) from spend), 0),
    'recentInvoices', coalesce((
      select jsonb_agg(row_to_json(x)::jsonb)
        from (select id, ref, student_name "studentName", course_code "course", campus_location "campus", amount_vnd "amountVnd",
                     status, method, receipt_no "receiptNo", created_at "createdAt", paid_at "paidAt"
                from inv order by (status = 'PENDING_PAYMENT') desc, coalesce(paid_at, created_at) desc limit 20) x), '[]'::jsonb),
    'queues', jsonb_build_object(
      'attendanceRequests', (select count(*) from public.attendance_requests r join public.students s on s.id = r.student_id
                              where r.status = 'PENDING' and (p_branch is null or s.campus_location = p_branch)),
      'newLeads', (select count(*) from public.leads where status = 'NEW' and (p_branch is null or branch_location = p_branch)),
      'commentsToday', (select count(*) from public.video_comments where created_at >= (v_today::timestamp at time zone 'Asia/Ho_Chi_Minh') and not is_hidden),
      'deletionRequests', (select count(*) from public.account_deletion_requests where status = 'PENDING'),
      'openTasks', (select count(*) from public.staff_tasks where status in ('PENDING', 'IN_PROGRESS')))
  ) into v_out;
  return v_out;
end $$;
grant execute on function public.admin_command_overview(text, int, timestamptz) to authenticated;

-- ─── Classes vs today's contact book ────────────────────────────────────────

create or replace function public.admin_class_report_status(p_branch text default null, p_date date default null)
returns table (class_id uuid, class_name text, course_code text, campus text, teacher_name text, slot text,
               students int, attended int, reports int)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_date date := coalesce(p_date, (now() at time zone 'Asia/Ho_Chi_Minh')::date);
  v_d int := extract(isodow from v_date)::int + 1;   -- schedule uses 2 (Thứ 2) … 8 (Chủ nhật)
begin
  perform public.admin_guard();
  perform public.admin_branch_check(p_branch);
  return query
    select c.id, c.name, c.course_code, c.campus_location,
           coalesce(sp.display_name, split_part(coalesce(u.email, ''), '@', 1), 'Chưa phân công'),
           (select string_agg((s ->> 'start') || '–' || (s ->> 'end'), ', ') from jsonb_array_elements(c.schedule) s where (s ->> 'd')::int = v_d),
           (select count(*)::int from public.class_members m where m.class_id = c.id),
           (select count(*)::int from public.attendance_logs a where a.class_id = c.id and a.session_date = v_date and a.status in ('PRESENT', 'LATE')),
           (select count(*)::int from public.class_members m join public.daily_reports d on d.enrollment_id = m.enrollment_id
             where m.class_id = c.id and d.session_date = v_date)
      from public.classes c
      left join public.staff_profiles sp on sp.user_id = c.teacher_id
      left join auth.users u on u.id = c.teacher_id
     where c.is_active
       and (p_branch is null or c.campus_location = p_branch)
       and exists (select 1 from jsonb_array_elements(c.schedule) s where (s ->> 'd')::int = v_d)
     order by 6 nulls last, c.name;
end $$;
grant execute on function public.admin_class_report_status(text, date) to authenticated;

-- ─── Comments (moderation) ──────────────────────────────────────────────────

create or replace function public.admin_recent_comments(p_filter text default 'ALL', p_limit int default 50)
returns table (id uuid, video_id uuid, video_title text, author_name text, author_role text, content text,
               is_hidden boolean, is_reply boolean, created_at timestamptz)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.admin_guard();
  if coalesce(p_filter, 'ALL') not in ('ALL', 'VISIBLE', 'HIDDEN', 'QUESTIONS') then
    raise exception 'Bộ lọc không hợp lệ' using hint = 'VALIDATION:filter';
  end if;
  return query
    select c.id, c.video_id, v.title, c.author_name, c.author_role, c.content, c.is_hidden, c.parent_comment_id is not null, c.created_at
      from public.video_comments c
      join public.videos v on v.id = c.video_id
     where case coalesce(p_filter, 'ALL')
             when 'VISIBLE' then not c.is_hidden
             when 'HIDDEN' then c.is_hidden
             -- Parent / guest questions nobody from the centre has answered yet.
             when 'QUESTIONS' then not c.is_hidden and c.parent_comment_id is null and c.author_role in ('PARENT', 'GUEST')
                                   and not exists (select 1 from public.video_comments r where r.parent_comment_id = c.id and r.author_role in ('TEACHER', 'ADMIN'))
             else true end
     order by c.created_at desc
     limit least(greatest(coalesce(p_limit, 50), 1), 200);
end $$;
grant execute on function public.admin_recent_comments(text, int) to authenticated;

-- ─── System health ──────────────────────────────────────────────────────────

create or replace function public.admin_system_health()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_week date := public.week_monday(public.vn_today()) - 7;
begin
  perform public.admin_guard();
  return jsonb_build_object(
    'push', jsonb_build_object(
      'pending', (select count(*) from public.push_outbox where status in ('PENDING', 'PROCESSING')),
      'failed24h', (select count(*) from public.push_outbox where status = 'FAILED' and created_at >= now() - interval '24 hours'),
      'sent24h', (select count(*) from public.push_outbox where status = 'SENT' and created_at >= now() - interval '24 hours'),
      'oldestPendingAt', (select min(created_at) from public.push_outbox where status in ('PENDING', 'PROCESSING')),
      'devices', (select count(*) from public.device_push_tokens)),
    'weeklyDigest', jsonb_build_object(
      'weekStart', v_week,
      'published', (select count(*) from public.weekly_progress_reports where week_start_date = v_week and published_at is not null),
      'zaloSent', (select count(*) from public.weekly_progress_reports where week_start_date = v_week and zalo_notified_at is not null),
      'drafts', (select count(*) from public.weekly_progress_reports where week_start_date = v_week and published_at is null)),
    'zalo', jsonb_build_object(
      'connected', exists (select 1 from public.zalo_oa_tokens),
      'expiresAt', (select max(access_expires_at) from public.zalo_oa_tokens),
      'lastError', (select last_error from public.zalo_oa_tokens limit 1),
      'lastErrorAt', (select last_error_at from public.zalo_oa_tokens limit 1)),
    'release', coalesce((select jsonb_agg(jsonb_build_object('platform', platform, 'min', min_supported_version, 'latest', latest_version,
                                                             'force', is_force_update, 'updatedAt', updated_at) order by platform)
                           from public.app_release_config), '[]'::jsonb)
  );
end $$;
grant execute on function public.admin_system_health() to authenticated;

-- ───────────────── 20261205090000_video_presenters.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Video presenters: the teachers who appear on EduFeed videos and Before/After posts
-- ("Cô Hường", "Thầy Tú"…) with their avatar — editable in the app by staff, so a new photo
-- no longer needs a code change.
--
--   video_presenters                       name (unique, case-insensitive), avatar_url, sort, is_active
--   video_presenters_list()                staff: active presenters + how many videos use each name
--   video_presenter_save(id, name, avatar, apply_existing)
--                                          staff: add / rename / change avatar; optionally copy the
--                                          new name + avatar onto existing videos and Before/After posts
--   video_presenter_archive(id)            admin: hide from the picker (old videos keep their name)
--
-- Avatars are uploaded to the public "avatars" bucket (20261203 account center), inside the
-- uploader's own <auth uid>/ folder.
-- ═══════════════════════════════════════════════════════════════════════════

create table if not exists public.video_presenters (
  id          uuid primary key default gen_random_uuid(),
  name        text not null check (char_length(btrim(name)) between 2 and 60),
  avatar_url  text check (avatar_url is null or (avatar_url ~* '^https://' and char_length(avatar_url) <= 500)),
  sort        smallint not null default 100,
  is_active   boolean not null default true,
  updated_by  uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create unique index if not exists video_presenters_name_key on public.video_presenters (lower(btrim(name)));
drop trigger if exists video_presenters_set_updated_at on public.video_presenters;
create trigger video_presenters_set_updated_at before update on public.video_presenters for each row execute function public.set_updated_at();

alter table public.video_presenters enable row level security;
revoke all on public.video_presenters from anon, authenticated;

-- Seed the two teachers the app shipped with; their avatar comes from the newest video that has one.
insert into public.video_presenters (name, sort, avatar_url)
select n, s, (select v.teacher_avatar_url from public.videos v
               where lower(btrim(v.teacher_name)) = lower(n) and v.teacher_avatar_url ~* '^https://' and v.teacher_avatar_url !~* 'pravatar\.cc'
               order by v.created_at desc limit 1)
  from (values ('Cô Hường', 1), ('Thầy Tú', 2)) as t(n, s)
on conflict do nothing;

-- ─── List ───────────────────────────────────────────────────────────────────

create or replace function public.video_presenters_list()
returns table (id uuid, name text, avatar_url text, sort smallint, videos int)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_staff() then
    raise exception 'Chỉ nhân viên TH EDU' using hint = 'FORBIDDEN';
  end if;
  return query
    select p.id, p.name, p.avatar_url, p.sort,
           (select count(*)::int from public.videos v where lower(btrim(v.teacher_name)) = lower(btrim(p.name)))
      from public.video_presenters p
     where p.is_active
     order by p.sort, p.name;
end $$;
grant execute on function public.video_presenters_list() to authenticated;

-- ─── Save ───────────────────────────────────────────────────────────────────

create or replace function public.video_presenter_save(p_id uuid, p_name text, p_avatar_url text, p_apply_existing boolean default true)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name   text := btrim(coalesce(p_name, ''));
  v_avatar text := nullif(btrim(coalesce(p_avatar_url, '')), '');
  v_old    public.video_presenters;
  v_row    public.video_presenters;
  v_videos int := 0;
  v_posts  int := 0;
begin
  if not public.is_staff() then
    raise exception 'Chỉ nhân viên TH EDU' using hint = 'FORBIDDEN';
  end if;
  if char_length(v_name) < 2 or char_length(v_name) > 60 then
    raise exception 'Tên giáo viên cần 2–60 ký tự' using hint = 'VALIDATION:name';
  end if;
  if v_name ~ '[<>{}]|https?://' then
    raise exception 'Tên không được chứa đường link hay ký tự đặc biệt' using hint = 'VALIDATION:name';
  end if;
  if v_avatar is not null and (v_avatar !~* '^https://' or char_length(v_avatar) > 500) then
    raise exception 'Ảnh đại diện không hợp lệ' using hint = 'VALIDATION:avatar';
  end if;
  if exists (select 1 from public.video_presenters x
              where lower(btrim(x.name)) = lower(v_name) and (p_id is null or x.id <> p_id) and x.is_active) then
    raise exception 'Đã có giáo viên tên "%"', v_name using hint = 'CONFLICT';
  end if;

  if p_id is null then
    -- Re-adding an archived name brings it back.
    update public.video_presenters set is_active = true, avatar_url = coalesce(v_avatar, avatar_url), updated_by = auth.uid()
     where lower(btrim(name)) = lower(v_name) and not is_active
    returning * into v_row;
    if v_row.id is null then
      insert into public.video_presenters (name, avatar_url, sort, updated_by)
      values (v_name, v_avatar, coalesce((select max(sort) + 1 from public.video_presenters), 1), auth.uid())
      returning * into v_row;
    end if;
  else
    select * into v_old from public.video_presenters where id = p_id for update;
    if not found then
      raise exception 'Không tìm thấy giáo viên' using hint = 'NOT_FOUND';
    end if;
    update public.video_presenters set name = v_name, avatar_url = v_avatar, updated_by = auth.uid()
     where id = p_id returning * into v_row;
    -- Existing videos / posts that show the old name get the new name + avatar.
    if coalesce(p_apply_existing, true) then
      update public.videos set teacher_name = v_name, teacher_avatar_url = v_avatar
       where lower(btrim(teacher_name)) = lower(btrim(v_old.name));
      get diagnostics v_videos = row_count;
      update public.portfolios set teacher_name = v_name, teacher_avatar_url = v_avatar
       where lower(btrim(teacher_name)) = lower(btrim(v_old.name));
      get diagnostics v_posts = row_count;
    end if;
  end if;

  return jsonb_build_object('id', v_row.id, 'name', v_row.name, 'avatarUrl', v_row.avatar_url,
                            'updatedVideos', v_videos, 'updatedPosts', v_posts);
end $$;
grant execute on function public.video_presenter_save(uuid, text, text, boolean) to authenticated;

-- ─── Archive ────────────────────────────────────────────────────────────────

create or replace function public.video_presenter_archive(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'Chỉ quản trị viên được ẩn giáo viên' using hint = 'FORBIDDEN';
  end if;
  update public.video_presenters set is_active = false, updated_by = auth.uid() where id = p_id;
  if not found then
    raise exception 'Không tìm thấy giáo viên' using hint = 'NOT_FOUND';
  end if;
end $$;
grant execute on function public.video_presenter_archive(uuid) to authenticated;

-- ───────────────── 20261206090000_security_hardening.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Hardening: account / admin / presenter functions are for signed-in users only.
-- Postgres grants EXECUTE to PUBLIC by default, so anon could call them; each one already
-- refuses guests inside ("Cần đăng nhập" / "Chỉ quản trị viên"), this removes the entry point too.
-- Public features (feed, comments, booking, certificates, payments…) are not touched.
-- ═══════════════════════════════════════════════════════════════════════════

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.account_role()',
    'public.my_account()',
    'public.update_my_profile(text, text)',
    'public.request_account_deletion(text)',
    'public.cancel_account_deletion()',
    'public.admin_deletion_requests(text)',
    'public.admin_resolve_deletion(uuid, text)',
    'public.admin_release_config_save(text, text, text, text, text, boolean)',
    'public.admin_ad_spend_save(text, text, date, bigint, text)',
    'public.admin_command_overview(text, int, timestamptz)',
    'public.admin_class_report_status(text, date)',
    'public.admin_recent_comments(text, int)',
    'public.admin_system_health()',
    'public.video_presenters_list()',
    'public.video_presenter_save(uuid, text, text, boolean)',
    'public.video_presenter_archive(uuid)'
  ] loop
    execute format('revoke execute on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end $$;

